  "Wave": "Ola",
  "WAVE": "ONDA",
  "Wave {round}/{total}: new enemies incoming!": "Ola {round}/{total}: ¡nuevos enemigos en camino!",
  "Wave {wave} begins.": "Comienza la onda {wave}.",
  "Wave {wave} Complete": "Ola {wave} Completa",
